const list = []
const push = (title, url, size) => list.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 0,
        "layout_flexBasisPercent": size || 0.29
    }
});

const urls = JSON.parse(java.base64Decode(getBaseUrls()));

Object.values(fx).forEach(({ title: n, fx: items }) => {
  push(n, "", 1, 1);
  items.forEach(({ title, id }) => {
    if (!id) {
      push(title, "", 1, 1);
    } else {
      push(title, urls[n].replace("$id", id));
    }
  });
});

JSON.stringify(list)

